/**
 * Generated files (commons 0024-ifws-host FR-003, FR-004, FR-007, FR-008): a template is a TypeScript function from data to a list of `GeneratedFile`s, and a generated file is made only
 * here, so that its path is a `RepoPath` inside the root, its name carries `.auto.` (a Git hook, whose name Git fixes and which lives in `.if-workspaces/hooks/`, is the one exception), its header names
 * its generator and says it is not to be edited, and its bytes are the same for the same data on every operating system: UTF-8 with no byte-order mark, LF line endings and one final newline.
 *
 * @remarks
 * There is no template language here: no parser, no `eval`, no `new Function` and no interpolation of data into code; a file's body is text a template built, or JSON a template built as a value, which
 * `generated` writes with the header as its first member (`_generated`). A path that holds `..`, is absolute or names a drive is refused by `repoPath` before any file exists. Two files whose
 * paths are one after Unicode normalization and case folding are both refused and named (0023-if-workspaces FR-011), and a file inside a repository's working tree is refused (FR-008).
 *
 * @module
 */
import { absurd } from "../kernel/absurd.ts";
import type { JsonObject } from "../kernel/json5.ts";
import { err, ok, type Result } from "../kernel/result.ts";
import { type Sha256, sha256 } from "../kernel/sha256.ts";
import { collisions, describePortableError, foldKey, repoPath } from "./portable.ts";
import type { RepoPath } from "./types.ts";

/** The mode of a generated file: `0644`, or `0755` for a script. */
export type FileMode = "0644" | "0755";

/** What a template gives of a file's body, by its format; the header is added by `generated`. */
export type FileBody =
  | { readonly format: "json"; readonly value: JsonObject }
  | { readonly format: "markdown"; readonly text: string }
  | { readonly format: "yaml"; readonly text: string }
  | { readonly format: "envrc"; readonly text: string }
  | { readonly format: "sh"; readonly text: string };

/** A file a template makes (`ifws:GeneratedFile`). */
export type GeneratedFile = {
  /** Its path below the root, with `/` between segments. */
  readonly path: RepoPath;
  /** Its bytes as text: header included, LF only, one final newline. */
  readonly content: string;
  readonly mode: FileMode;
  /** The generator the header names, such as `ifws templates/agents`. */
  readonly generator: string;
};

/** Why a file was refused. */
export type GenerateError =
  | { readonly kind: "bad-path"; readonly path: string; readonly reason: string }
  | { readonly kind: "not-auto"; readonly path: string }
  | { readonly kind: "collision"; readonly path: string; readonly other: string }
  | { readonly kind: "inside-repository"; readonly path: string; readonly repository: string }
  | { readonly kind: "bad-data"; readonly what: string; readonly reason: string };

/** A refusal as one sentence. */
export function describeGenerateError(e: GenerateError): string {
  switch (e.kind) {
    case "bad-path":
      return `${JSON.stringify(e.path)} cannot be the path of a generated file: ${e.reason}`;
    case "not-auto":
      return `${e.path} is a generated file whose name does not carry .auto. (only a Git hook in .if-workspaces/hooks/ may lack it)`;
    case "collision":
      return `${e.path} is the same path as ${e.other} after Unicode normalization and case folding; both are refused`;
    case "inside-repository":
      return `${e.path} is inside the working tree of ${e.repository}; a generated file is never written into a repository`;
    case "bad-data":
      return `${e.what}: ${e.reason}`;
    default:
      return absurd(e);
  }
}

/** The folder of the hooks, below the root. */
export const HOOKS_FOLDER = ".if-workspaces/hooks";

/** The text of the header of a generated file: what made it, and that it is not to be edited. */
export function headerText(generator: string): string {
  return `Generated by ${generator}. Do not edit by hand: change workspace.ts and run \`ifws render\`.`;
}

/** Text as a generated file keeps it: LF line endings, no byte-order mark, exactly one final newline. */
export function normalizeText(text: string): string {
  const lf = text.replace(/^﻿/, "").replaceAll("\r\n", "\n").replaceAll("\r", "\n");
  return `${lf.replace(/\n+$/, "")}\n`;
}

/** Whether a file name carries `.auto.` (`AGENTS.auto.md`) or ends in `.auto` (`.envrc.auto`). */
export function isAutoName(name: string): boolean {
  return name.includes(".auto.") || name.endsWith(".auto");
}

/** A path as a generated file's: portable segments, never absolute, never `..`, never a drive. */
export function generatedPath(path: string): Result<RepoPath, GenerateError> {
  const made = repoPath(path.split("/"));
  if (made.kind === "err") return err({ kind: "bad-path", path, reason: describePortableError(made.error) });
  return made;
}

const noBom = (text: string): string => text.replace(/^\uFEFF/, "");

function contentOf(body: FileBody, generator: string): string {
  const header = headerText(generator);
  switch (body.format) {
    case "json":
      return normalizeText(JSON.stringify({ _generated: header, ...body.value }, null, 2));
    case "markdown":
      return normalizeText(`<!-- ${header} -->\n\n${noBom(body.text)}`);
    case "yaml":
    case "envrc":
      return normalizeText(`# ${header}\n\n${noBom(body.text)}`);
    case "sh": {
      // a script's first line is its interpreter; the header comes after it
      const text = noBom(body.text);
      const m = /^(#![^\n]*)\n/.exec(text);
      return m === null ? normalizeText(`# ${header}\n${text}`) : normalizeText(`${m[1]}\n# ${header}\n${text.slice(m[0].length)}`);
    }
    default:
      return absurd(body);
  }
}

/**
 * A generated file: its path checked, its name checked to carry `.auto.` (a hook in `.if-workspaces/hooks/` excepted), its header added, its bytes normalized. The same arguments give the same bytes.
 */
export function generated(
  path: string,
  body: FileBody,
  options: { readonly generator: string; readonly mode?: FileMode },
): Result<GeneratedFile, GenerateError> {
  const made = generatedPath(path);
  if (made.kind === "err") return made;
  const name = made.value.split("/").at(-1) ?? "";
  const isHook = made.value.startsWith(`${HOOKS_FOLDER}/`) && made.value.split("/").length === 3;
  if (!isAutoName(name) && !isHook) return err({ kind: "not-auto", path });
  return ok({ path: made.value, content: contentOf(body, options.generator), mode: options.mode ?? "0644", generator: options.generator });
}

/** The SHA-256 of a generated file's bytes. */
export function fileDigest(file: GeneratedFile): Promise<Sha256> {
  return sha256(file.content);
}

/**
 * A set of files checked together: two whose paths are one after folding are refused (each naming the other), and so is one inside the working tree of a repository of the workspace
 * (`repositories` are their paths below the root). The files are returned in the order of their paths, folded, so that the same data gives the same order.
 */
export function checkFiles(
  files: readonly GeneratedFile[],
  repositories: readonly string[],
): Result<readonly GeneratedFile[], readonly GenerateError[]> {
  const errors: GenerateError[] = [];
  for (const c of collisions(files.map((f) => ({ id: f.path, path: f.path })))) {
    for (const m of c.members) {
      const other = c.members.find((o) => o !== m);
      errors.push({ kind: "collision", path: m.path, other: other?.path ?? m.path });
    }
  }
  for (const f of files) {
    const key = foldKey(f.path);
    const inside = repositories.find((r) => key.startsWith(`${foldKey(r)}/`));
    if (inside !== undefined) errors.push({ kind: "inside-repository", path: f.path, repository: inside });
  }
  if (errors.length > 0) return err(errors);
  return ok([...files].sort((a, b) => (foldKey(a.path) < foldKey(b.path) ? -1 : foldKey(a.path) > foldKey(b.path) ? 1 : 0)));
}
